-- Additive only: existing INR records and immutable ledger entries are never rewritten.
CREATE TABLE wallet_links(id TEXT PRIMARY KEY,userId TEXT NOT NULL REFERENCES users(id),network TEXT NOT NULL CHECK(network='STELLAR_TESTNET'),address TEXT NOT NULL,verifiedAt TEXT NOT NULL,disconnectedAt TEXT);
CREATE UNIQUE INDEX active_user_wallet ON wallet_links(userId,network) WHERE disconnectedAt IS NULL;
CREATE UNIQUE INDEX active_wallet_owner ON wallet_links(network,address) WHERE disconnectedAt IS NULL;
CREATE TABLE wallet_challenges(id TEXT PRIMARY KEY,userId TEXT NOT NULL REFERENCES users(id),sessionHash TEXT NOT NULL,origin TEXT NOT NULL,network TEXT NOT NULL CHECK(network='STELLAR_TESTNET'),address TEXT NOT NULL,nonce TEXT NOT NULL UNIQUE,xdr TEXT NOT NULL,serverKey TEXT NOT NULL,expiresAt INTEGER NOT NULL,usedAt TEXT);
CREATE TABLE chain_escrows(id TEXT PRIMARY KEY,projectId TEXT NOT NULL REFERENCES projects(id),agreementId TEXT NOT NULL REFERENCES agreements(id),network TEXT NOT NULL CHECK(network='STELLAR_TESTNET'),contractId TEXT NOT NULL,escrowId TEXT NOT NULL,termsHash TEXT NOT NULL,clientAddress TEXT NOT NULL,freelancerAddress TEXT NOT NULL,resolverAddress TEXT NOT NULL,assetId TEXT NOT NULL,state TEXT NOT NULL,createdAt TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),UNIQUE(network,contractId,escrowId),UNIQUE(agreementId));
CREATE TABLE chain_milestones(escrowRef TEXT NOT NULL REFERENCES chain_escrows(id),milestoneId TEXT NOT NULL REFERENCES milestones(id),chainId TEXT NOT NULL,amount TEXT NOT NULL,funded TEXT NOT NULL DEFAULT '0',paid TEXT NOT NULL DEFAULT '0',refunded TEXT NOT NULL DEFAULT '0',state TEXT NOT NULL DEFAULT 'AwaitingFunding',submissionHash TEXT,PRIMARY KEY(escrowRef,milestoneId),UNIQUE(escrowRef,chainId));
CREATE TABLE chain_transactions(id TEXT PRIMARY KEY,userId TEXT NOT NULL REFERENCES users(id),projectId TEXT NOT NULL REFERENCES projects(id),escrowRef TEXT NOT NULL REFERENCES chain_escrows(id),milestoneId TEXT REFERENCES milestones(id),network TEXT NOT NULL CHECK(network='STELLAR_TESTNET'),contractId TEXT NOT NULL,method TEXT NOT NULL,operationKey TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('CREATED','AWAITING_SIGNATURE','SIGNED','SUBMITTED','PENDING','CONFIRMED','FAILED','EXPIRED','RECONCILIATION_REQUIRED')),xdr TEXT,signedXdr TEXT,txHash TEXT,expected TEXT NOT NULL CHECK(json_valid(expected)),result TEXT,error TEXT,expiresAt INTEGER,createdAt TEXT NOT NULL,updatedAt TEXT NOT NULL,UNIQUE(network,txHash));
CREATE UNIQUE INDEX one_active_chain_operation ON chain_transactions(operationKey) WHERE status NOT IN ('FAILED','EXPIRED');
CREATE TABLE chain_confirmations(transactionId TEXT PRIMARY KEY REFERENCES chain_transactions(id),network TEXT NOT NULL,txHash TEXT NOT NULL,ledger INTEGER NOT NULL CHECK(ledger>0),confirmedAt TEXT NOT NULL,state TEXT NOT NULL CHECK(json_valid(state)),UNIQUE(network,txHash));
CREATE TABLE chain_events(network TEXT NOT NULL,txHash TEXT NOT NULL,eventIndex INTEGER NOT NULL,contractId TEXT NOT NULL,ledger INTEGER NOT NULL,topics TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(network,txHash,eventIndex));
CREATE TABLE chain_sync(network TEXT NOT NULL,contractId TEXT NOT NULL,lastLedger INTEGER NOT NULL DEFAULT 0,updatedAt TEXT NOT NULL,PRIMARY KEY(network,contractId));
CREATE TRIGGER immutable_chain_confirmation_update BEFORE UPDATE ON chain_confirmations BEGIN SELECT RAISE(ABORT,'Chain confirmations are immutable'); END;
CREATE TRIGGER immutable_chain_confirmation_delete BEFORE DELETE ON chain_confirmations BEGIN SELECT RAISE(ABORT,'Chain confirmations are immutable'); END;
CREATE TRIGGER fixed_chain_participants BEFORE UPDATE ON chain_escrows WHEN OLD.contractId<>NEW.contractId OR OLD.escrowId<>NEW.escrowId OR OLD.termsHash<>NEW.termsHash OR OLD.clientAddress<>NEW.clientAddress OR OLD.freelancerAddress<>NEW.freelancerAddress OR OLD.resolverAddress<>NEW.resolverAddress OR OLD.assetId<>NEW.assetId BEGIN SELECT RAISE(ABORT,'Escrow terms and participants are fixed'); END;
CREATE TRIGGER immutable_financial_mode BEFORE UPDATE ON projects WHEN COALESCE(json_extract(OLD.data,'$.financialMode'),'LOCAL_DEMO')<>COALESCE(json_extract(NEW.data,'$.financialMode'),'LOCAL_DEMO') BEGIN SELECT RAISE(ABORT,'Project financial mode is immutable'); END;
